import java.util.PriorityQueue

fun kLargest(nums: IntArray, k: Int): List<Int> {
    val minHeap = PriorityQueue<Int>()
    for (x in nums) {
        minHeap.add(x)
        if (minHeap.size > k) minHeap.poll()      // drop the smallest
    }
    return minHeap.toList()                        // the K largest (unordered)
}
// Time: O(n log k)   Space: O(k)

import java.util.PriorityQueue

fun kSmallest(nums: IntArray, k: Int): List<Int> {
    val maxHeap = PriorityQueue<Int>(compareByDescending { it })
    for (x in nums) {
        maxHeap.add(x)
        if (maxHeap.size > k) maxHeap.poll()      // drop the largest
    }
    return maxHeap.toList()
}
// Time: O(n log k)   Space: O(k)

import java.util.PriorityQueue

// Keep the K items with the largest score
fun topKByScore(items: List<Pair<String, Int>>, k: Int): List<String> {
    val minHeap = PriorityQueue<Pair<String, Int>>(compareBy { it.second })
    for (item in items) {
        minHeap.add(item)
        if (minHeap.size > k) minHeap.poll()
    }
    return minHeap.sortedByDescending { it.second }.map { it.first }
}
// Time: O(n log k)   Space: O(k)

import java.util.PriorityQueue

fun findKthLargest(nums: IntArray, k: Int): Int {
    val minHeap = PriorityQueue<Int>()
    for (x in nums) {
        minHeap.add(x)
        if (minHeap.size > k) minHeap.poll()
    }
    return minHeap.peek()                          // Kth largest
}
// Time: O(n log k)   Space: O(k)
