import java.util.PriorityQueue

fun topKFrequent(nums: IntArray, k: Int): IntArray {
    val freq = HashMap<Int, Int>()
    for (x in nums) freq[x] = (freq[x] ?: 0) + 1

    // min heap ordered by frequency
    val heap = PriorityQueue<Map.Entry<Int, Int>>(compareBy { it.value })
    for (entry in freq.entries) {
        heap.add(entry)
        if (heap.size > k) heap.poll()
    }
    return heap.map { it.key }.toIntArray()
}
// Time: O(n log k)   Space: O(n)

import java.util.PriorityQueue

fun topKFrequentWords(words: Array<String>, k: Int): List<String> {
    val freq = HashMap<String, Int>()
    for (w in words) freq[w] = (freq[w] ?: 0) + 1

    // min heap: lowest frequency first; for equal frequency, alphabetically LARGER first
    val heap = PriorityQueue<String>(Comparator { a, b ->
        if (freq[a] == freq[b]) b.compareTo(a)
        else freq[a]!! - freq[b]!!
    })
    for (w in freq.keys) {
        heap.add(w)
        if (heap.size > k) heap.poll()
    }
    val result = mutableListOf<String>()
    while (heap.isNotEmpty()) result.add(heap.poll())
    return result.reversed()                       // highest frequency first
}
// Time: O(n log k)   Space: O(n)

import java.util.PriorityQueue

fun kClosest(points: Array<IntArray>, k: Int): Array<IntArray> {
    // max heap by squared distance: farthest of the kept points on top
    val maxHeap = PriorityQueue<IntArray>(compareByDescending { it[0] * it[0] + it[1] * it[1] })
    for (p in points) {
        maxHeap.add(p)
        if (maxHeap.size > k) maxHeap.poll()       // remove the farthest
    }
    return maxHeap.toTypedArray()
}
// Time: O(n log k)   Space: O(k)

import java.util.PriorityQueue

class KthLargest(private val k: Int, nums: IntArray) {
    private val minHeap = PriorityQueue<Int>()

    init {
        for (x in nums) add(x)
    }

    fun add(value: Int): Int {
        minHeap.add(value)
        if (minHeap.size > k) minHeap.poll()
        return minHeap.peek()
    }
}
// Each add: O(log k)   Space: O(k)

import java.util.PriorityQueue

fun kthSmallest(matrix: Array<IntArray>, k: Int): Int {
    val n = matrix.size
    // heap of [value, row, col], start with the first column
    val minHeap = PriorityQueue<IntArray>(compareBy { it[0] })
    for (r in 0 until minOf(n, k)) minHeap.add(intArrayOf(matrix[r][0], r, 0))

    var result = 0
    repeat(k) {
        val (value, r, c) = minHeap.poll()
        result = value
        if (c + 1 < n) minHeap.add(intArrayOf(matrix[r][c + 1], r, c + 1))
    }
    return result
}
// Time: O(k log n)   Space: O(n)

import java.util.PriorityQueue

fun reorganizeString(s: String): String {
    val freq = IntArray(26)
    for (c in s) freq[c - 'a']++
    val maxHeap = PriorityQueue<Pair<Char, Int>>(compareByDescending { it.second })
    for (i in 0 until 26) {
        if (freq[i] > 0) maxHeap.add(Pair('a' + i, freq[i]))
    }
    val sb = StringBuilder()
    var prev: Pair<Char, Int>? = null
    while (maxHeap.isNotEmpty()) {
        val (ch, count) = maxHeap.poll()
        sb.append(ch)
        prev?.let { if (it.second > 0) maxHeap.add(it) }     // put the previous one back
        prev = Pair(ch, count - 1)
    }
    return if (sb.length == s.length) sb.toString() else ""
}
// Time: O(n log 26)   Space: O(1)

import java.util.PriorityQueue

fun connectRopes(ropes: IntArray): Int {
    val minHeap = PriorityQueue<Int>()
    for (r in ropes) minHeap.add(r)
    var cost = 0
    while (minHeap.size > 1) {
        val a = minHeap.poll()
        val b = minHeap.poll()
        cost += a + b                       // cost of joining the two shortest
        minHeap.add(a + b)
    }
    return cost
}
// Time: O(n log n)   Space: O(n)

import java.util.PriorityQueue

fun sumBetween(nums: IntArray, k1: Int, k2: Int): Int {
    val maxHeap = PriorityQueue<Int>(compareByDescending { it })
    for (x in nums) {
        maxHeap.add(x)
        if (maxHeap.size > k2 - 1) maxHeap.poll()   // keep the k2 - 1 smallest
    }
    var sum = 0
    repeat(k2 - k1 - 1) { sum += maxHeap.poll() }   // the numbers strictly between
    return sum
}
// Time: O(n log k2)   Space: O(k2)

import java.util.PriorityQueue

fun kSmallestPairs(nums1: IntArray, nums2: IntArray, k: Int): List<List<Int>> {
    val result = mutableListOf<List<Int>>()
    if (nums1.isEmpty() || nums2.isEmpty()) return result
    // heap of [sum, i, j]
    val minHeap = PriorityQueue<IntArray>(compareBy { it[0] })
    for (i in 0 until minOf(nums1.size, k)) {
        minHeap.add(intArrayOf(nums1[i] + nums2[0], i, 0))
    }
    while (result.size < k && minHeap.isNotEmpty()) {
        val (_, i, j) = minHeap.poll()
        result.add(listOf(nums1[i], nums2[j]))
        if (j + 1 < nums2.size) {
            minHeap.add(intArrayOf(nums1[i] + nums2[j + 1], i, j + 1))
        }
    }
    return result
}
// Time: O(k log k)   Space: O(k)
